import { 
  World, 
  BoxGeometry, 
  Mesh, 
  MeshStandardMaterial, 
  AmbientLight 
} from '@iwsdk/core';
import projectOptions from 'virtual:iwsdk-project';

// Use the exact container ID generated by IWSDK (usually 'scene')
const container = document.getElementById('scene') as HTMLDivElement || document.getElementById('scene-container') as HTMLDivElement;

World.create(container, projectOptions).then((world) => {
  console.log("Spatial Music Visualizer initialized successfully!");

  // Add lighting so standard materials aren't pitch black
  const ambientLight = new AmbientLight(0xffffff, 1.2);
  world.scene.add(ambientLight);

  // Create our visualizer box
  const geometry = new BoxGeometry(0.3, 0.3, 0.3);
  const material = new MeshStandardMaterial({ 
    color: 0x00ffcc, 
    emissive: 0x004444 
  });
  
  const coreMesh = new Mesh(geometry, material);
  coreMesh.position.set(0, 1.2, -0.6); // Seated 2-foot radius in front of user
  
  // Add to world scene
  world.scene.add(coreMesh);

  // Simple animation loop
  let time = 0;
  world.renderer.setAnimationLoop((timestamp, frame) => {
    time += 0.016 * 3;
    const scale = 1 + Math.sin(time) * 0.15;
    coreMesh.scale.set(scale, scale, scale);
  });
});
